'use strict';
const $=id=>document.getElementById(id),selector=$('preview-state');
function showState(state){selector.value=state;document.querySelectorAll('.game-state').forEach(el=>el.hidden=el.id!==`game-${state==='soon'?'ready':state}`);$('start-game').disabled=state==='soon';$('start-game').textContent=state==='soon'?'COMING SOON':'START RUN →';$('attempt-status').textContent=state==='soon'?'COMING SOON':state==='used'?'RUN COMPLETE':'RUN AVAILABLE';$('game-instructions').textContent=state==='soon'?'A new daily challenge is on its way. Come back for a little wordplay soon.':'Six letters. Plenty of possibilities. Build your best word and make this little break count.';const url=new URL(location.href);url.searchParams.set('state',state);history.replaceState(null,'',url);}
selector.onchange=()=>showState(selector.value);const initial=new URLSearchParams(location.search).get('state');showState(['ready','playing','results','used','soon'].includes(initial)?initial:'ready');
$('start-game').onclick=()=>showState('playing');$('demo-finish').onclick=()=>showState('results');document.querySelectorAll('.mode-option').forEach(b=>b.onclick=()=>{document.querySelectorAll('.mode-option').forEach(x=>{x.classList.toggle('is-selected',x===b);x.setAttribute('aria-pressed',String(x===b));});showState('ready');});$('sound-toggle').onclick=()=>{const muted=$('sound-toggle').getAttribute('aria-pressed')!=='true';$('sound-toggle').setAttribute('aria-pressed',String(muted));$('sound-toggle').textContent=muted?'Sound: off':'Sound: on';};
async function copy(text){try{await navigator.clipboard.writeText(text);$('copy-status').textContent='Copied!';}catch{$('copy-status').textContent='Copy is unavailable in this browser. Try the preview in a secure browser tab.';}}$('share-result').onclick=()=>copy('Break Room · Word Forge · Template preview · 84/100');$('share-top').onclick=()=>copy(location.href);
let active=null,opener=null;const shade=document.createElement('div');shade.className='menu-shade';shade.hidden=true;document.body.append(shade);const menu=$('game-menu');menu.setAttribute('role','dialog');menu.setAttribute('aria-modal','true');
function close(){if(!active)return;active.hidden=true;menu.setAttribute('aria-hidden','true');$('game-menu-toggle').setAttribute('aria-expanded','false');shade.hidden=true;document.querySelectorAll('[data-preview-inert]').forEach(el=>{el.inert=false;delete el.dataset.previewInert;});document.body.style.overflow='';active=null;opener?.focus();}
function open(el,button){active=el;opener=button;document.body.append(el);el.hidden=false;document.body.style.overflow='hidden';[...document.body.children].filter(x=>x!==el&&x!==shade&&!['SCRIPT','LINK'].includes(x.tagName)).forEach(x=>{x.inert=true;x.dataset.previewInert='';});if(el===menu){shade.hidden=false;menu.setAttribute('aria-hidden','false');button.setAttribute('aria-expanded','true');}el.querySelector('button,a').focus();}
['help','stats'].forEach(type=>{$(`${type}-popup-open`).onclick=e=>open($(`${type}-popup`),e.currentTarget);$(`${type}-popup`).onclick=e=>{if(e.target===$(`${type}-popup`))close();};});document.querySelectorAll('[data-popup-close]').forEach(b=>b.onclick=close);$('game-menu-toggle').onclick=e=>open(menu,e.currentTarget);$('game-menu-close').onclick=close;shade.onclick=close;document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape')close();if(e.key==='Tab'&&active){const list=[...active.querySelectorAll('button:not(:disabled),a[href],select')],first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
